/* ticket 17. The pages that write their own <img> tags — About's photo
   strips and certificates, Showcase's wall, the Gallery quick-view — look
   their file up here rather than carrying a copy of the ladder in the
   markup. Key is the src exactly as the page writes it ('img/...').
   `sizes` may be overridden per call: the same file is painted at 584px in
   About's portrait and at 36px in a byline avatar. */
window.CAS_IMG_ATTRS = function (src, sizes) {
  var m = (window.CAS_IMG || {})[src];
  if (!m) return '';
  var esc = function (s) { return String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;'); };
  return ' srcset="' + esc(m.srcset) + '"'
       + ' sizes="' + esc(sizes || m.sizes) + '"'
       + ' width="' + m.w + '" height="' + m.h + '"';
};
